function validate(input) {
  const [{ Activities = [], Age = [] }] = input;
  const users = new Set(), activities = new Set();
  for (const [user, bucket] of Age) {
    if (user === null) return 'Every Age row needs a user_id.';
    if (users.has(user)) return `user_id ${user} appears twice in Age.`;
    users.add(user);
    if (!['21-25', '26-30', '31-35'].includes(bucket)) return `age_bucket must be 21-25, 26-30 or 31-35, not ${bucket}.`;
  }
  for (const [id, user, type, spent] of Activities) {
    if (id === null) return 'Every activity needs an activity_id.';
    if (activities.has(id)) return `activity_id ${id} appears twice.`;
    activities.add(id);
    if (!users.has(user)) return `User ${user} of activity ${id} is missing from Age.`;
    if (type !== 'send' && type !== 'open') return `activity_type must be send or open, not ${type}.`;
    if (spent === null || spent <= 0 || spent > 999.99) return `Activity ${id} needs a time_spent between 0.01 and 999.99.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const buckets = ['21-25', '26-30', '31-35'];
  const times = [0.5, 1.25, 2, 3, 3.5, 4.5, 5.25, 5.67, 6.24, 8.24];
  const userCount = size === 'small' ? pick(6) : 1000;
  const activityCount = size === 'small' ? (userCount ? pick(9) : 0) : 2000;
  const Age = [];
  for (let i = 0; i < userCount; i++) Age.push([size === 'small' ? 100 + i * 111 : 1 + i * 3, buckets[pick(buckets.length)]]);
  const Activities = [], ids = new Set();
  for (let i = 0; i < activityCount; i++) {
    let id;
    do id = 1000 + pick(size === 'small' ? 9000 : 90000); while (ids.has(id));
    ids.add(id);
    const spent = size === 'small' ? times[pick(times.length)] : (1 + pick(9999)) / 100;
    Activities.push([id, Age[pick(Age.length)][0], rand() < 0.5 ? 'send' : 'open', spent]);
  }
  return [{ Activities, Age }];
}
